#!/usr/bin/env bash
set -e
cd ~
mkdir -p caiyunju && cd caiyunju
echo "解压代码..."
cat <<'B64END' | base64 -d > /tmp/cyj.tar.gz

B64END
tar xzf /tmp/cyj.tar.gz -C ~/caiyunju/
rm /tmp/cyj.tar.gz
chmod +x ~/caiyunju/server-marketSign/install.sh
echo "代码已解压到 ~/caiyunju/server-marketSign/"
echo "现在跑 install.sh..."
bash ~/caiyunju/server-marketSign/install.sh
